using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
public static class ValidatePajeroDynamicsV2
{
 static ForestKamazController car;static Rigidbody rb;static VehiclePhysics drive;
 static void Step(){car.SendMessage("Update");car.SendMessage("FixedUpdate");Physics.Simulate(Time.fixedDeltaTime);car.SendMessage("LateUpdate");car.GetComponent<TruckBrakeLights>().SendMessage("LateUpdate");}
 static void Place(Vector3 p,Quaternion q){rb.position=p;rb.rotation=q;car.transform.SetPositionAndRotation(p,q);rb.linearVelocity=Vector3.zero;rb.angularVelocity=Vector3.zero;drive.ResetState();car.testThrottle=0;car.testSteer=0;car.testBrake=false;car.lowRange=false;car.reverseGear=false;Physics.SyncTransforms();}
 static void Steps(int count){for(int i=0;i<count;i++)Step();}
 public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play");car=UnityEngine.Object.FindAnyObjectByType<ForestKamazController>();rb=car.GetComponent<Rigidbody>();drive=car.GetComponent<VehiclePhysics>();if(drive==null)throw new Exception("No drivetrain");var position=rb.position;var rotation=rb.rotation;var mode=Physics.simulationMode;bool paused=EditorApplication.isPaused;var fixture=GameObject.CreatePrimitive(PrimitiveType.Cube);fixture.transform.position=new Vector3(500,19.5f,500);fixture.transform.localScale=new Vector3(400,1,400);string report="";
 try{Physics.simulationMode=SimulationMode.Script;EditorApplication.isPaused=true;car.testControl=true;Place(new Vector3(500,20.5f,500),Quaternion.identity);car.testThrottle=-1;Steps(250);if(car.wheels.Count(w=>w.isGrounded)!=4)throw new Exception("Suspension contacts missing");
 car.testThrottle=1;Steps(20);float pedal=drive.Pedal;if(pedal>.2f)throw new Exception("Instant full throttle="+pedal);Steps(480);float speed=car.SpeedKmh;float rpm=drive.EngineRpm;if(speed<7||speed>50)throw new Exception("Invalid first-gear acceleration speed="+speed+" rpm="+rpm+" pedal="+drive.Pedal+" torque="+car.wheels[2].motorTorque);report+="pedal@0.2s="+pedal.ToString("F2")+", 5s first gear="+speed.ToString("F1")+"km/h @"+rpm.ToString("F0")+"rpm; ";
 drive.Shift(1);Steps(150);if(drive.Gear!=2)throw new Exception("Gear failed");car.testThrottle=0;Steps(30);float coast=car.SpeedKmh;if(coast<speed*.45f)throw new Exception("No coast");car.testThrottle=-1;Steps(400);if(car.SpeedKmh>.8f||!car.GetComponent<TruckBrakeLights>().Illuminated)throw new Exception("Service braking failed="+car.SpeedKmh);report+="brakes="+car.SpeedKmh.ToString("F2")+"km/h; ";
 Place(new Vector3(500,20.5f,500),Quaternion.identity);car.testThrottle=-1;Steps(150);drive.SetNeutral(true);car.testThrottle=1;Steps(300);float free=drive.EngineRpm;car.testThrottle=0;Steps(150);if(free<3000||drive.EngineRpm>free-400)throw new Exception("Free rev response failed "+free+" -> "+drive.EngineRpm);report+="neutral rev="+free.ToString("F0")+" -> "+drive.EngineRpm.ToString("F0")+"rpm; ";
 var mud=fixture.AddComponent<ForestDrivingSurface>();mud.cover=ForestDrivingSurface.Cover.Mud;mud.forwardGrip=.16f;mud.lateralGrip=.30f;mud.rollingResistance=.07f;Place(new Vector3(500,20.5f,500),Quaternion.identity);car.testThrottle=-1;Steps(150);car.lowRange=true;car.testThrottle=1;float spin=0,maxRpm=0;for(int i=0;i<450;i++){Step();spin=Mathf.Max(spin,drive.WheelspinSpeed);maxRpm=Mathf.Max(maxRpm,drive.EngineRpm);}if(spin<1.5f||maxRpm<1800)throw new Exception("No physical wheelspin "+spin+" rpm="+maxRpm);report+="mud spin="+spin.ToString("F1")+"m/s @"+maxRpm.ToString("F0")+"rpm; ";UnityEngine.Object.DestroyImmediate(mud);
 Place(new Vector3(500,20.5f,500),Quaternion.identity);car.testThrottle=-1;Steps(150);rb.linearVelocity=Vector3.forward*11.5f;car.testThrottle=.45f;car.testSteer=.65f;float slip=0,roll=0;for(int i=0;i<160;i++){car.testBrake=i<35;Step();slip=Mathf.Max(slip,Mathf.Abs(drive.SlipAngle));roll=Mathf.Max(roll,Vector3.Angle(car.transform.up,Vector3.up));}float before=Mathf.Abs(drive.SlipAngle);car.testBrake=false;for(int i=0;i<300;i++){car.testThrottle=.15f;car.testSteer=Mathf.Clamp(drive.SlipAngle/25,-.8f,.8f);Step();}float after=Mathf.Abs(drive.SlipAngle);if(slip<7||roll>55||after>Mathf.Max(9,before*.8f))throw new Exception("Drift/recovery failed peak="+slip+" roll="+roll+" recovery="+before+" -> "+after);report+="drift peak="+slip.ToString("F1")+"deg, recovery="+before.ToString("F1")+" -> "+after.ToString("F1")+"deg, roll="+roll.ToString("F1")+"deg; ";
 return "PASS progressive pedal, flywheel RPM, gears, braking/coasting, mud wheelspin and countersteer recovery. "+report;
 }finally{UnityEngine.Object.DestroyImmediate(fixture);car.testControl=false;car.testThrottle=0;car.testSteer=0;car.testBrake=false;Place(position,rotation);Physics.simulationMode=mode;EditorApplication.isPaused=paused;}
 }
}
